import{_ as e}from"./chunks/page-selection.B_Erd84k.js";import{_ as o,a as n}from"./chunks/input-polish-replace.D1noCAnv.js";import{_ as a,o as i,c as s,a2 as l}from"./chunks/framework.CfwCq2QB.js";const r="/dev-go-docs/shots/0.2.3/en/light/options-selection.png",q=JSON.parse('{"title":"Selection toolbar & custom actions","description":"","frontmatter":{},"headers":[],"relativePath":"en/features/selection-toolbar.md","filePath":"en/features/selection-toolbar.md"}'),c={name:"en/features/selection-toolbar.md"};function h(p,t,u,d,g,m){return i(),s("div",null,[...t[0]||(t[0]=[l('<h1 id="selection-toolbar-custom-actions" tabindex="-1">Selection toolbar &amp; custom actions <a class="header-anchor" href="#selection-toolbar-custom-actions" aria-label="Permalink to &quot;Selection toolbar &amp; custom actions&quot;">​</a></h1><p>In one line: select text on a page and a toolbar appears above it — translate, explain, summarize, or ask AI. Select text in an input field and the toolbar switches to writing mode: polish, fix, or formalize, then replace the original in one click.</p><h2 id="on-page-text" tabindex="-1">On page text <a class="header-anchor" href="#on-page-text" aria-label="Permalink to &quot;On page text&quot;">​</a></h2><p>Select text and the toolbar pops up:</p><ul><li><strong>Translate</strong>: translates the selection; a single English word also shows dictionary definitions</li><li><strong>Explain / Summarize</strong>: the AI reads the surrounding paragraph and page title for context</li><li><strong>Ask AI</strong>: opens the side panel with the selection attached</li><li>More than four actions fold into the &quot;More&quot; menu</li></ul><img src="'+e+'" alt="Selection toolbar"><p><em>The selection toolbar on page text.</em></p><p>The result panel sits right below the selection and follows it as the page scrolls; pin it to freeze it on screen, or drag it anywhere. The bottom row supports <strong>Copy</strong>, <strong>Follow up</strong>, and <strong>Retry</strong>.</p><img src="'+o+'" alt="The result panel of an Explain action: action switcher on top, AI answer below, follow-up and copy at the bottom"><p><em>The &quot;Explain&quot; result panel: switch actions at the top; follow up or copy at the bottom.</em></p><h2 id="in-input-fields" tabindex="-1">In input fields <a class="header-anchor" href="#in-input-fields" aria-label="Permalink to &quot;In input fields&quot;">​</a></h2><p>Select text inside an input (comment boxes, search boxes, web editors) and the toolbar switches to writing mode: <strong>Polish, Fix, Formal</strong>, plus your custom actions that apply to inputs. When the AI finishes, click &quot;Replace original&quot; to swap the field&#39;s content for the result.</p><img src="'+n+'" alt="Writing mode inside an input: Polish / Fix / Formal toolbar and a result panel with a Replace original button"><p><em>Writing mode in an input field — after the AI polishes the text, &quot;Replace original&quot; swaps it in. (Screenshot shows the Chinese UI; an English version is pending.)</em></p><h2 id="custom-actions" tabindex="-1">Custom actions <a class="header-anchor" href="#custom-actions" aria-label="Permalink to &quot;Custom actions&quot;">​</a></h2><p>When the built-ins aren&#39;t enough, add your own under Settings → Selection → Toolbar actions → Add action:</p><ul><li><strong>Name</strong>: shown on the toolbar, e.g. &quot;Translate to English&quot;</li><li><strong>Icon</strong>: pick from 12 common icons</li><li><strong>Applies to</strong>: Page text / Input fields / Both</li><li><strong>Prompt</strong>: tell the AI how to handle the selection, e.g. &quot;organize the selection into clean JSON and output only the JSON&quot;</li></ul><p>No need to wire up context yourself — like built-in actions, requests automatically attach the paragraph around the selection and the page title.</p><p>Three example templates ship built-in, one click to add: <strong>Translate to English</strong>, <strong>Explain the error</strong>, <strong>Convert to JSON</strong>.</p><p>The management area also supports edit, delete (with confirmation), and move up / move down; built-in actions can be hidden individually. The toolbar shows up to four actions directly — the rest go into &quot;More&quot;.</p><img src="'+r+'" alt="Selection settings"><p><em>Settings → Selection → Toolbar actions: built-in action switches and custom action management.</em></p><h2 id="toggles" tabindex="-1">Toggles <a class="header-anchor" href="#toggles" aria-label="Permalink to &quot;Toggles&quot;">​</a></h2><ul><li><strong>Global switch</strong>: Settings → Selection → &quot;Enable selection&quot;; &quot;AI actions&quot; can be turned off separately (translation only)</li><li><strong>Per site</strong>: the popup&#39;s Features page has a switch for the current site only — turning it off shows &quot;Off on {host}&quot;. The list is managed under Settings → Selection → &quot;Sites where selection is off&quot;</li></ul><h2 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;Notes&quot;">​</a></h2><ul><li>AI actions need a <a href="/dev-go-docs/en/settings/models.html">chat model</a> (the translation model is used until one is set separately). With no model or API key configured, the result panel says so and a &quot;<strong>Set up</strong>&quot; button jumps to Settings → AI models; an invalid key (401 / 403) shows the same button</li><li>For one annoying site — an online editor, say — use per-site off rather than killing the global switch</li><li>Custom actions are included in <a href="/dev-go-docs/en/settings/sync.html">backup export / import</a>, so they survive a machine switch</li></ul>',26)])])}const x=a(c,[["render",h]]);export{q as __pageData,x as default};
